L["UFGroupHealerBuffEditorRuleInfoBarDrain"] = "Affichage des règles pour %s. La portée est définie par règle (Groupe/Raid/Cible/Focalisation/Boss). L'animation de vidange suit la première aura temporisée active de cette liste."
L["UFGroupHealerBuffEditorRuleInfoBarDrainColor"] = "Affichage des règles pour %s. La portée est définie règle par règle (Groupe/Raid/Cible/Focalisation/Boss). La couleur suit la première règle active de cette liste. Les étapes de couleur de durée peuvent remplacer la couleur selon le temps d'aura restant. L'animation de vidage suit la première aura active temporisée de cette liste. Les remplacements de couleur de sort sont définis par règle (clic droit pour réinitialiser)."
