L["UFGroupHealerBuffEditorRuleInfoIconDynamic"] = "Affichage des règles pour %s. La portée est définie par règle (Groupe/Raid/Cible/Focalisation/Boss). Les icônes actives remplissent la limite configurée et sont triées automatiquement."
L["UFGroupHealerBuffEditorRuleInfoSquare"] = "Affichage des règles pour %s. La portée est définie par règle (Groupe/Raid/Cible/Focalisation/Boss). La priorité suit l'ordre des règles dans cette liste. Les étapes de couleur de durée peuvent remplacer la couleur selon le temps d'aura restant. Les remplacements de couleur du sort sont définis par règle (clic droit pour réinitialiser)."
L["UFGroupHealerBuffEditorRuleInfoTint"] = "Affichage des règles pour %s. La portée est définie par règle (Groupe/Raid/Cible/Focalisation/Boss). La teinte peut exiger n'importe quel sort actif ou tous."
L["UFGroupHealerBuffEditorRuleInfoTintColor"] = "Affichage des règles pour %s. La portée est définie règle par règle (Groupe/Raid/Cible/Focalisation/Boss). La teinte peut exiger n'importe quels sorts actifs ou l'ensemble des sorts actifs. Lorsque plusieurs règles sont actives, la couleur suit la première règle correspondante de cette liste. Les remplacements de couleur de sort sont définis par règle (clic droit pour réinitialiser)."
